// Extract and analyze the JS from the built HTML
const fs = require('fs');
const html = fs.readFileSync('dist/mcp-app.html', 'utf8');
const scriptMatch = html.match(/<script[^>]*type=\"module\"[^>]*>([\s\S]*?)<\/script>/);
if (scriptMatch) {
  const js = scriptMatch[1];
  // Check for common error patterns
  const issues = [];

  // Check for unresolved imports
  if (js.includes('require(')) issues.push('Found require() calls in module script');

  // Check for node-only APIs
  if (js.includes('process.env')) issues.push('Found process.env references');
  if (js.includes('__dirname')) issues.push('Found __dirname references');

  // Check for CSS import statements  
  const cssImports = js.match(/import[^;]*\.css/g);
  if (cssImports) issues.push('Found CSS imports: ' + cssImports.join(', '));

  // Look for potential throw/error patterns at module level
  const topLevelThrows = js.match(/^throw\s/gm);
  if (topLevelThrows) issues.push('Found top-level throws');

  if (issues.length > 0) {
    console.log('Potential issues found:');
    issues.forEach(i => console.log('  -', i));
  } else {
    console.log('No obvious issues found in script analysis');
  }

  // Check last 100 chars to see the entry point call
  console.log('Script entry (last 100 chars):', js.slice(-100));
  console.log('Script length:', js.length);
}
" 2>&1

