// Try to parse the JS module contents for obvious errors
const fs = require('fs');
const html = fs.readFileSync('dist/mcp-app.html', 'utf8');
const scriptMatch = html.match(/<script[^>]*type=\"module\"[^>]*>([\s\S]*?)<\/script>/);
if (!scriptMatch) { console.log('No module script found'); process.exit(1); }
const js = scriptMatch[1];

// Look for the SemioKit / Section / Breadcrumb component chain
// Find all named function/class definitions
const patterns = [
  // Check if @elements/ui components are bundled
  { name: 'Section render', pattern: /mb-8/, found: false },
  { name: 'Breadcrumb', pattern: /breadcrumb|data-slot.*crumb/i, found: false },
  { name: 'Button with text', pattern: /Open Artifact|Clear/, found: false },
  { name: 'Kit Artifacts title', pattern: /Kit Artifacts/, found: false },
  { name: 'useApp hook', pattern: /semio design viewer/, found: false },
  { name: 'Connecting text', pattern: /Connecting to host/, found: false },
  { name: 'Waiting text', pattern: /Waiting for design data/, found: false },
  { name: 'Error display', pattern: /Error:/, found: false },
  { name: 'PostMessageTransport', pattern: /PostMessageTransport|window\.parent/, found: false },
];

for (const p of patterns) {
  p.found = p.pattern.test(js);
  console.log(\`[\${p.found ? 'OK' : 'MISSING'}] \${p.name}\`);
}
" 2>&1

