import re
with open('dist/mcp-app.html', 'r') as f:
    content = f.read()

# Check for potential issues in sandboxed iframe
issues = []

# 1. Check for localStorage/sessionStorage usage (not available in sandboxed iframe)
if 'localStorage' in content:
    issues.append('Uses localStorage (not available in sandboxed iframe)')
if 'sessionStorage' in content:
    issues.append('Uses sessionStorage')

# 2. Check for window.location usage
loc_usage = content.count('window.location')
if loc_usage: issues.append(f'Uses window.location ({loc_usage} times)')

# 3. Check for document.cookie
if 'document.cookie' in content:
    issues.append('Uses document.cookie')

# 4. Check for new Function or eval
if 'new Function' in content:
    issues.append('Uses new Function (CSP violation)')
if re.search(r'[^a-zA-Z]eval\(', content):
    issues.append('Uses eval() (CSP violation)')

# 5. Check for fetch or XMLHttpRequest
fetch_count = content.count('fetch(')
if fetch_count: issues.append(f'Uses fetch() ({fetch_count} times)')

# 6. Check for 'crossorigin' attribute  
crossorigin = content.count('crossorigin')
if crossorigin: issues.append(f'Uses crossorigin attribute ({crossorigin} times)')

for i in issues:
    print(f'Issue: {i}')
if not issues:
    print('No sandbox issues found')
"

